import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it("returns 0 for any input", () => {
    expect(calc.computeTaxCents(10000, "US")).toBe(0);
  });

  it("returns 0 for zero taxable", () => {
    expect(calc.computeTaxCents(0, "US")).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  it("rejects defaultRate < 0", () => {
    expect(() => new RegionalTaxCalculator({}, -0.01)).toThrow(RangeError);
  });

  it("rejects defaultRate > 1", () => {
    expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
  });

  it("rejects NaN defaultRate", () => {
    expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
  });

  it("rejects invalid rate in rates map", () => {
    expect(() => new RegionalTaxCalculator({ "US": 1.5 })).toThrow(RangeError);
  });

  it("rejects negative rate in rates map", () => {
    expect(() => new RegionalTaxCalculator({ "US": -0.1 })).toThrow(RangeError);
  });

  it("uses region-specific rate when available", () => {
    const calc = new RegionalTaxCalculator({ "US-CA": 0.0875, "US-TX": 0.0625 });
    // 8.75% of 10000 = 875
    expect(calc.computeTaxCents(10000, "US-CA")).toBe(875);
  });

  it("falls back to default rate for unknown region", () => {
    const calc = new RegionalTaxCalculator({ "US-CA": 0.0875 }, 0.05);
    // 5% of 10000 = 500
    expect(calc.computeTaxCents(10000, "FR")).toBe(500);
  });

  it("defaults defaultRate to 0 when not specified", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.1 });
    expect(calc.computeTaxCents(10000, "FR")).toBe(0);
  });

  it("rounds down fractional cents", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.07 });
    // 7% of 999 = 69.93 → 69
    expect(calc.computeTaxCents(999, "US")).toBe(69);
  });

  it("returns 0 for zero taxable", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.1 });
    expect(calc.computeTaxCents(0, "US")).toBe(0);
  });

  it("returns 0 for negative taxable", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.1 });
    expect(calc.computeTaxCents(-1000, "US")).toBe(0);
  });

  it("accepts boundary rate 0", () => {
    const calc = new RegionalTaxCalculator({ "US": 0 });
    expect(calc.computeTaxCents(10000, "US")).toBe(0);
  });

  it("accepts boundary rate 1", () => {
    const calc = new RegionalTaxCalculator({ "US": 1 });
    expect(calc.computeTaxCents(10000, "US")).toBe(10000);
  });
});

describe("AsyncTaxCalculator", () => {
  it("computes tax from async provider rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };
    const calc = new AsyncTaxCalculator(provider);
    // 8% of 5000 = 400
    expect(await calc.computeTaxCents(5000, "US")).toBe(400);
    expect(provider.getRate).toHaveBeenCalledWith("US");
  });

  it("rounds down fractional cents", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.07),
    };
    const calc = new AsyncTaxCalculator(provider);
    // 7% of 999 = 69.93 → 69
    expect(await calc.computeTaxCents(999, "US")).toBe(69);
  });

  it("returns 0 for zero taxable without calling provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(0, "US")).toBe(0);
  });

  it("returns 0 for negative taxable", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(-500, "US")).toBe(0);
  });

  it("throws RangeError for rate > 1", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(1.5),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for negative rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(-0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for NaN rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(NaN),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("network error")),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow("network error");
  });
});

describe("totalLineWeightGrams", () => {
  it("sums weight * quantity across lines", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100, weightGrams: 500 }, quantity: 2 },
      { product: { id: "b", name: "B", unitPriceCents: 200, weightGrams: 300 }, quantity: 3 },
    ];
    // 500*2 + 300*3 = 1900
    expect(totalLineWeightGrams(lines)).toBe(1900);
  });

  it("treats missing weightGrams as 0", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 5 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });

  it("returns 0 for empty array", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });
});

import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  unitPriceCents: number,
  quantity: number,
  weightGrams?: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("always returns 0", () => {
    expect(calc.computeShippingCents([makeLine("a", 100, 1)], 100)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  it("rejects negative flatCents", () => {
    expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
  });

  it("rejects non-integer flatCents", () => {
    expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
  });

  it("rejects negative freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
  });

  it("rejects non-integer freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, 99.5)).toThrow(RangeError);
  });

  it("returns flatCents for non-empty cart below threshold", () => {
    const calc = new FlatShippingCalculator(500, 5000);
    expect(calc.computeShippingCents([makeLine("a", 100, 1)], 4999)).toBe(500);
  });

  it("returns 0 when subtotal equals freeOverCents threshold", () => {
    const calc = new FlatShippingCalculator(500, 5000);
    expect(calc.computeShippingCents([makeLine("a", 5000, 1)], 5000)).toBe(0);
  });

  it("returns 0 when subtotal exceeds freeOverCents threshold", () => {
    const calc = new FlatShippingCalculator(500, 5000);
    expect(calc.computeShippingCents([makeLine("a", 6000, 1)], 6000)).toBe(0);
  });

  it("returns flatCents when no threshold set", () => {
    const calc = new FlatShippingCalculator(500);
    expect(calc.computeShippingCents([makeLine("a", 100000, 1)], 100000)).toBe(500);
  });

  it("returns 0 for empty cart", () => {
    const calc = new FlatShippingCalculator(500);
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });

  it("accepts 0 flatCents", () => {
    const calc = new FlatShippingCalculator(0);
    expect(calc.computeShippingCents([makeLine("a", 100, 1)], 100)).toBe(0);
  });
});

describe("WeightBasedShippingCalculator", () => {
  it("rejects empty brackets array", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow(
      "at least one weight bracket is required",
    );
  });

  it("rejects bracket with non-positive upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("rejects bracket with negative costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
    ).toThrow(RangeError);
  });

  it("rejects negative overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 1000, costCents: 100 }],
          -1,
        ),
    ).toThrow(RangeError);
  });

  it("rejects non-integer overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 1000, costCents: 100 }],
          5.5,
        ),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });

  it("returns 0 when total weight is 0", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    // line with no weight
    expect(calc.computeShippingCents([makeLine("a", 100, 1)], 100)).toBe(0);
  });

  it("selects the correct bracket by weight", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 5000, costCents: 1000 },
    ]);
    // 400g → first bracket
    expect(
      calc.computeShippingCents([makeLine("a", 100, 1, 400)], 100),
    ).toBe(300);
    // 500g → first bracket (inclusive upper bound)
    expect(
      calc.computeShippingCents([makeLine("a", 100, 1, 500)], 100),
    ).toBe(300);
    // 501g → second bracket
    expect(
      calc.computeShippingCents([makeLine("a", 100, 1, 501)], 100),
    ).toBe(500);
    // 1000g → second bracket
    expect(
      calc.computeShippingCents([makeLine("a", 100, 1, 1000)], 100),
    ).toBe(500);
    // 3000g → third bracket
    expect(
      calc.computeShippingCents([makeLine("a", 100, 1, 3000)], 100),
    ).toBe(1000);
  });

  it("sorts brackets by upToGrams regardless of input order", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 5000, costCents: 1000 },
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(
      calc.computeShippingCents([makeLine("a", 100, 1, 400)], 100),
    ).toBe(300);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ],
      2000,
    );
    expect(
      calc.computeShippingCents([makeLine("a", 100, 1, 5000)], 100),
    ).toBe(2000);
  });

  it("defaults overflow to heaviest bracket cost", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(
      calc.computeShippingCents([makeLine("a", 100, 1, 5000)], 100),
    ).toBe(500);
  });

  it("sums weight across multiple lines", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
    ]);
    // 200*2 + 300*1 = 700g → second bracket
    const lines: CartLine[] = [
      makeLine("a", 100, 2, 200),
      makeLine("b", 100, 1, 300),
    ];
    expect(calc.computeShippingCents(lines, 200)).toBe(500);
  });
});

import { describe, it, expect, vi } from "vitest";
import {
  InventoryError,
  refreshPrices,
  type PriceFetcher,
} from "../src/inventory.ts";
import type { CartLine } from "../src/product.ts";

describe("InventoryError", () => {
