describe("refreshPrices", () => {
  it("updates unitPriceCents from fetcher", async () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 2 },
      { product: { id: "b", name: "B", unitPriceCents: 200 }, quantity: 1 },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(150)
        .mockResolvedValueOnce(250),
    };

    const result = await refreshPrices(lines, fetcher);
    expect(result).toHaveLength(2);
    expect(result[0]!.product.unitPriceCents).toBe(150);
    expect(result[0]!.quantity).toBe(2);
    expect(result[1]!.product.unitPriceCents).toBe(250);
    expect(result[1]!.quantity).toBe(1);
  });

  it("does not mutate original lines", async () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 1 },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };

    await refreshPrices(lines, fetcher);
    expect(lines[0]!.product.unitPriceCents).toBe(100);
  });

  it("throws RangeError for negative price", async () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 1 },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-5),
    };

    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer price", async () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 1 },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };

    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 1 },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("service down")),
    };

    await expect(refreshPrices(lines, fetcher)).rejects.toThrow("service down");
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product, CartLine } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
} from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import { RegionalTaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";
import { InventoryError } from "../src/inventory.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const productA: Product = { id: "a", name: "Widget A", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Widget B", unitPriceCents: 2000, weightGrams: 500 };

describe("Cart", () => {
  describe("add", () => {
    it("adds a new product", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantity for existing product", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      cart.add(productA, 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects non-positive quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(productA, 0)).toThrow(RangeError);
      expect(() => cart.add(productA, -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const cart = new Cart();
      const badProduct: Product = { id: "bad", name: "Bad", unitPriceCents: -1 };
      expect(() => cart.add(badProduct, 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes existing product and returns true", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity is 0", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("nonexistent", 1)).toThrow(
        "Product nonexistent is not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("empties the cart", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 2);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns deep copy that doesn't affect internal state", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const snap = cart.snapshot();
      (snap[0] as { quantity: number }).quantity = 999;
      expect(cart.itemCount).toBe(1);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of unitPriceCents * quantity", () => {
      const cart = new Cart();
      cart.add(productA, 2); // 2000
      cart.add(productB, 1); // 2000
      const t = cart.totals();
      expect(t.subtotalCents).toBe(4000);
    });

    it("empty cart has all-zero totals", () => {
      const cart = new Cart();
      const t = cart.totals();
      expect(t).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("applies discount policy", () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
      });
      cart.add(productA, 1); // subtotal 1000
      const t = cart.totals();
      expect(t.discountCents).toBe(100);
      expect(t.totalCents).toBe(900);
    });

    it("clamps discount to [0, subtotal]", () => {
      // A policy that returns more than subtotal
      const overDiscount: DiscountPolicy = {
        computeDiscountCents: () => 999999,
      };
      const cart = new Cart({ discountPolicy: overDiscount });
      cart.add(productA, 1); // subtotal 1000
      const t = cart.totals();
      expect(t.discountCents).toBe(1000); // clamped to subtotal
    });

    it("clamps negative discount to 0", () => {
      const negDiscount: DiscountPolicy = {
        computeDiscountCents: () => -500,
      };
      const cart = new Cart({ discountPolicy: negDiscount });
      cart.add(productA, 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(0);
    });

    it("computes tax on discounted subtotal", () => {
      const cart = new Cart({
        discountPolicy: new FixedAmountDiscountPolicy(500),
        taxCalculator: new RegionalTaxCalculator({ "US": 0.1 }),
      });
      cart.add(productA, 1); // subtotal 1000, discount 500, taxable 500
      const t = cart.totals();
      expect(t.taxCents).toBe(50); // 10% of 500
    });

    it("pipeline order: subtotal → discount → tax → shipping", () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
        taxCalculator: new RegionalTaxCalculator({ "US": 0.1 }),
        shippingCalculator: new FlatShippingCalculator(500),
      });
      cart.add(productA, 1); // subtotal 1000
      const t = cart.totals();
      // discount: 20% of 1000 = 200
      expect(t.discountCents).toBe(200);
      // tax: 10% of 800 = 80
      expect(t.taxCents).toBe(80);
      // shipping: flat 500
      expect(t.shippingCents).toBe(500);
      // total: 800 + 80 + 500 = 1380
      expect(t.totalCents).toBe(1380);
    });

    it("uses default config when none provided", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const t = cart.totals();
      // defaults: no discount, no tax, free shipping
      expect(t.discountCents).toBe(0);
      expect(t.taxCents).toBe(0);
      expect(t.shippingCents).toBe(0);
      expect(t.totalCents).toBe(1000);
    });

    it("uses configured region for tax lookup", () => {
      const cart = new Cart({
        taxCalculator: new RegionalTaxCalculator({ "FR": 0.2, "US": 0.05 }),
        region: "FR",
      });
      cart.add(productA, 1); // subtotal 1000
      const t = cart.totals();
      expect(t.taxCents).toBe(200); // 20% of 1000
    });

    it("clamps negative tax to 0", () => {
      const negativeTax: TaxCalculator = {
        computeTaxCents: () => -100,
      };
      const cart = new Cart({ taxCalculator: negativeTax });
      cart.add(productA, 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const negativeShipping: ShippingCalculator = {
        computeShippingCents: () => -50,
      };
      const cart = new Cart({ shippingCalculator: negativeShipping });
      cart.add(productA, 1);
      expect(cart.totals().shippingCents).toBe(0);
    });
  });

  describe("checkout", () => {
    it("returns totals and lines without collaborators", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.lines).toHaveLength(1);
    });

    it("refreshes prices via priceFetcher", async () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const result = await cart.checkout({ priceFetcher });
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
      expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
    });

    it("checks inventory and passes for available items", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 1);
      expect(result.totals.subtotalCents).toBe(1000);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(productA, 5);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          reason: "out of stock",
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InstanceType<typeof InventoryError>;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(5);
      }
    });

    it("throws InventoryError on partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(productA, 10);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InstanceType<typeof InventoryError>;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(10);
        expect(err.available).toBe(3);
      }
    });

    it("uses asyncTaxProvider for tax computation", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(200),
      });
      cart.add(productA, 1); // subtotal 1000
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      // discount: 10% of 1000 = 100 → discounted subtotal = 900
      // tax: 8% of 900 = 72
      // shipping: 200
      expect(result.totals.discountCents).toBe(100);
      expect(result.totals.taxCents).toBe(72);
      expect(result.totals.shippingCents).toBe(200);
      expect(result.totals.totalCents).toBe(900 + 72 + 200);
    });

    it("propagates asyncTaxProvider rejection", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });

    it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
      const cart = new Cart({
        discountPolicy: new NoDiscountPolicy(),
        shippingCalculator: new FlatShippingCalculator(300),
      });
      cart.add(productA, 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(500),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // refreshed price: 500 each, qty 2 → subtotal 1000
      expect(result.totals.subtotalCents).toBe(1000);
      // no discount
      expect(result.totals.discountCents).toBe(0);
      // tax: 10% of 1000 = 100
      expect(result.totals.taxCents).toBe(100);
      // shipping: 300
      expect(result.totals.shippingCents).toBe(300);
      // total: 1000 + 100 + 300
      expect(result.totals.totalCents).toBe(1400);
    });

    it("priceFetcher rejection propagates", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("fetch failed");
    });

    it("inventory denial on second item stops checkout", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 3);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn()
          .mockResolvedValueOnce({ available: true })
          .mockResolvedValueOnce({ available: false, reason: "discontinued" }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InstanceType<typeof InventoryError>;
        expect(err.productId).toBe("b");
        expect(err.message).toBe("discontinued");
      }
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it("returns 0 for any input", () => {
    expect(calc.computeTaxCents(10000, "US")).toBe(0);
  });

  it("returns 0 for zero taxable", () => {
    expect(calc.computeTaxCents(0, "US")).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  it("rejects defaultRate < 0", () => {
    expect(() => new RegionalTaxCalculator({}, -0.01)).toThrow(RangeError);
  });

  it("rejects defaultRate > 1", () => {
    expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
  });

  it("rejects NaN defaultRate", () => {
    expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
  });

  it("rejects invalid rate in rates map", () => {
    expect(() => new RegionalTaxCalculator({ "US": 1.5 })).toThrow(RangeError);
  });

  it("rejects negative rate in rates map", () => {
    expect(() => new RegionalTaxCalculator({ "US": -0.1 })).toThrow(RangeError);
  });

  it("uses region-specific rate when available", () => {
    const calc = new RegionalTaxCalculator({ "US-CA": 0.0875, "US-TX": 0.0625 });
    // 8.75% of 10000 = 875
    expect(calc.computeTaxCents(10000, "US-CA")).toBe(875);
  });

  it("falls back to default rate for unknown region", () => {
    const calc = new RegionalTaxCalculator({ "US-CA": 0.0875 }, 0.05);
    // 5% of 10000 = 500
    expect(calc.computeTaxCents(10000, "FR")).toBe(500);
  });

  it("defaults defaultRate to 0 when not specified", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.1 });
    expect(calc.computeTaxCents(10000, "FR")).toBe(0);
  });

  it("rounds down fractional cents", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.07 });
    // 7% of 999 = 69.93 → 69
    expect(calc.computeTaxCents(999, "US")).toBe(69);
  });

  it("returns 0 for zero taxable", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.1 });
    expect(calc.computeTaxCents(0, "US")).toBe(0);
  });

  it("returns 0 for negative taxable", () => {
    const calc = new RegionalTaxCalculator({ "US": 0.1 });
    expect(calc.computeTaxCents(-1000, "US")).toBe(0);
  });

  it("accepts boundary rate 0", () => {
    const calc = new RegionalTaxCalculator({ "US": 0 });
    expect(calc.computeTaxCents(10000, "US")).toBe(0);
  });

  it("accepts boundary rate 1", () => {
    const calc = new RegionalTaxCalculator({ "US": 1 });
    expect(calc.computeTaxCents(10000, "US")).toBe(10000);
  });
});

describe("AsyncTaxCalculator", () => {
  it("computes tax from async provider rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };
    const calc = new AsyncTaxCalculator(provider);
    // 8% of 5000 = 400
    expect(await calc.computeTaxCents(5000, "US")).toBe(400);
    expect(provider.getRate).toHaveBeenCalledWith("US");
  });

  it("rounds down fractional cents", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.07),
    };
    const calc = new AsyncTaxCalculator(provider);
    // 7% of 999 = 69.93 → 69
    expect(await calc.computeTaxCents(999, "US")).toBe(69);
  });

  it("returns 0 for zero taxable without calling provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(0, "US")).toBe(0);
  });

  it("returns 0 for negative taxable", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(-500, "US")).toBe(0);
  });

  it("throws RangeError for rate > 1", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(1.5),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for negative rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(-0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for NaN rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(NaN),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("network error")),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow("network error");
  });
});

