{"file_text": "import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product, CartLine } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
} from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import { RegionalTaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";
import { InventoryError } from "../src/inventory.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const productA: Product = { id: "a", name: "Widget A", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Widget B", unitPriceCents: 2000, weightGrams: 500 };

describe("Cart", () => {
  describe("add", () => {
    it("adds a new product", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantity for existing product", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      cart.add(productA, 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects non-positive quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(productA, 0)).toThrow(RangeError);
      expect(() => cart.add(productA, -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const cart = new Cart();
      const badProduct: Product = { id: "bad", name: "Bad", unitPriceCents: -1 };
      expect(() => cart.add(badProduct, 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes existing product and returns true", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity is 0", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("nonexistent", 1)).toThrow(
        "Product nonexistent is not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("empties the cart", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 2);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns deep copy that doesn't affect internal state", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const snap = cart.snapshot();
      (snap[0] as { quantity: number }).quantity = 999;
      expect(cart.itemCount).toBe(1);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of unitPriceCents * quantity", () => {
      const cart = new Cart();
      cart.add(productA, 2); // 2000
      cart.add(productB, 1); // 2000
      const t = cart.totals();
      expect(t.subtotalCents).toBe(4000);
    });

    it("empty cart has all-zero totals", () => {
      const cart = new Cart();
      const t = cart.totals();
      expect(t).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("applies discount policy", () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
      });
      cart.add(productA, 1); // subtotal 1000
      const t = cart.totals();
      expect(t.discountCents).toBe(100);
      expect(t.totalCents).toBe(900);
    });

    it("clamps discount to [0, subtotal]", () => {
      // A policy that returns more than subtotal
      const overDiscount: DiscountPolicy = {
        computeDiscountCents: () => 999999,
      };
      const cart = new Cart({ discountPolicy: overDiscount });
      cart.add(productA, 1); // subtotal 1000
      const t = cart.totals();
      expect(t.discountCents).toBe(1000); // clamped to subtotal
    });

    it("clamps negative discount to 0", () => {
      const negDiscount: DiscountPolicy = {
        computeDiscountCents: () => -500,
      };
      const cart = new Cart({ discountPolicy: negDiscount });
      cart.add(productA, 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(0);
    });

    it("computes tax on discounted subtotal", () => {
      const cart = new Cart({
